"""Fix guidance for students: written by the team, per kind of issue, not generated by an LLM.

Every finding gets an entry: why it matters, 2-4 fix steps and a short corrected example in the language of the file
(Python, JavaScript/TypeScript or Java). `guidance_for(finding)` picks the entry by rule id first, then by CWE, then falls
back to a general entry for the category, so a finding never has no advice. The LLM may add a short note on top of this for
findings it confirmed (see interpreter/prompts.py); this table is what students always get.
"""

import re
from dataclasses import dataclass, field

from app.agents.security_assistant.schemas import Category, Finding

OWASP = "https://cheatsheetseries.owasp.org/cheatsheets/"
CWE_URL = "https://cwe.mitre.org/data/definitions/{}.html"


@dataclass(frozen=True)
class Guidance:
    id: str
    title: str
    category: Category
    why: str
    steps: tuple[str, ...]
    examples: dict[str, str] = field(default_factory=dict)  # language -> a few lines of corrected code
    reference: str = ""
    rules: tuple[str, ...] = ()  # regexes matched against the rule id
    cwes: tuple[str, ...] = ()


V1, V2, V3, V4, V5 = Category.V1, Category.V2, Category.V3, Category.V4, Category.V5

