_GENERAL = {g.category: g for g in GUIDANCE if g.id.startswith("general-")}
_LANGUAGE_BY_SUFFIX = {".py": "python", ".js": "javascript", ".jsx": "javascript", ".mjs": "javascript",
                       ".cjs": "javascript", ".ts": "javascript", ".tsx": "javascript", ".java": "java", ".kt": "java",
                       ".properties": "java", ".yml": "java", ".yaml": "java", ".xml": "java", ".gradle": "java",
                       ".lockfile": "java", ".txt": "python", ".json": "javascript"}


def guidance_for(f: Finding) -> Guidance:
    """By rule id first, then by CWE, then the general entry of the category."""
    specific = [g for g in GUIDANCE if not g.id.startswith("general-")]
    for g in specific:
        if g.category is f.category and any(re.search(r, f.rule_id) for r in g.rules):
            return g
    for g in specific:
        if f.cwe in g.cwes and (g.category is f.category or f.category in (V1, V2) and g.category in (V1, V2)):
            return g
    return _GENERAL[f.category]


def language_of(f: Finding) -> str | None:
    path = (f.file_path or "").lower()
    if path.startswith(".github/workflows/"):
        return "ci"
    if path.endswith(("pom.xml", "build.gradle", "build.gradle.kts", "gradle.lockfile")):
        return "java"
    if path.endswith(("requirements.txt", "pyproject.toml")):
        return "python"
    if path.endswith(("package.json", "package-lock.json", "yarn.lock")):
        return "javascript"
    suffix = "." + path.rsplit(".", 1)[-1] if "." in path else ""
    return _LANGUAGE_BY_SUFFIX.get(suffix)


def example_for(g: Guidance, f: Finding) -> tuple[str, str] | None:
    """(language, code) for the language of the finding's file, else the first example the entry has."""
    language = language_of(f)
    if language in g.examples:
        return language, g.examples[language]
    return next(iter(g.examples.items()), None)


def references(g: Guidance, f: Finding) -> list[str]:
    links = [g.reference] if g.reference else []
    if f.cwe and f.cwe.upper().startswith("CWE-") and f.cwe[4:].isdigit():
        links.append(CWE_URL.format(f.cwe[4:]))
    return links


def render_markdown(g: Guidance, findings: list[Finding]) -> str:
    """The guidance block of the report: why, steps, one example per language that occurs in `findings`."""
    lines = [f"**Why it matters.** {g.why}", "", "**How to fix it**", ""]
    lines += [f"{n}. {step}" for n, step in enumerate(g.steps, 1)]
    seen, shown = [], []
    for f in findings:
        ex = example_for(g, f)
        if ex and ex[0] not in seen:
            seen.append(ex[0])
            shown.append(ex)
    for language, code in shown:
        lines += ["", f"Example ({language}):", "", "```", code, "```"]
    refs = []
    for f in findings:
        refs += [r for r in references(g, f) if r not in refs]
    if refs:
        lines += ["", "Read more: " + ", ".join(refs)]
    return "\n".join(lines)


def prompt_text(g: Guidance, f: Finding) -> str:
    """The reference guidance as the LLM sees it (trusted text written by the team). The "why it matters" paragraph is left out:
    it is for the student's report, and the model only needs the steps and the example to write a tailored note."""
    out = [f"{g.title}.", "Steps: " + " ".join(f"({n}) {s}" for n, s in enumerate(g.steps, 1))]
    ex = example_for(g, f)
    if ex:
        out.append(f"Example ({ex[0]}):\n{ex[1]}")
    return "\n".join(out)


def by_id(guidance_id: str | None) -> Guidance | None:
    return next((g for g in GUIDANCE if g.id == guidance_id), None)
